'use strict';
const $=id=>document.getElementById(id);
const cats=[{name:'Food & drinks',color:'#5a836f',icon:'♧'},{name:'Transport',color:'#9bbba2',icon:'↗'},{name:'Shopping',color:'#c6b48e',icon:'◇'},{name:'Education',color:'#8b9da7',icon:'▤'},{name:'Entertainment',color:'#a6a0b5',icon:'▷'},{name:'Other',color:'#c9cfbc',icon:'⋯'}];
const payments=['UPI','Cash','Debit card','Credit card','Bank transfer'];
const dateStr=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const money=n=>'₹'+(n/100).toLocaleString('en-IN',{minimumFractionDigits:n%100?2:0,maximumFractionDigits:2});
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>Array.from(crypto.getRandomValues(new Uint8Array(16))).map(b=>b.toString(16).padStart(2,'0')).join('');
let state={expenses:[],budgets:{}},view='overview',pendingDelete=null,timer;
try{const raw=JSON.parse(localStorage.getItem('pocketwise-v1')||'null');if(raw&&Array.isArray(raw.expenses)&&raw.budgets&&typeof raw.budgets==='object'){state.expenses=raw.expenses.filter(e=>e&&typeof e.id==='string'&&typeof e.title==='string'&&Number.isSafeInteger(e.amount)&&e.amount>0&&/^\d{4}-\d{2}-\d{2}$/.test(e.date)&&cats.some(c=>c.name===e.category)&&payments.includes(e.payment));for(const [m,b]of Object.entries(raw.budgets)){if(/^\d{4}-\d{2}$/.test(m)&&b&&typeof b==='object'){state.budgets[m]={};for(const c of cats){const n=b[c.name];if(Number.isSafeInteger(n)&&n>=0)state.budgets[m][c.name]=n}}}}}catch{setTimeout(()=>toast('Saved data could not be loaded. Start fresh or check your browser settings.'),50)}
function save(){try{localStorage.setItem('pocketwise-v1',JSON.stringify(state));return true}catch{toast('Your browser could not save changes. Please enable browser storage.');return false}}
function commit(next){const old=state;state=next;if(!save()){state=old;return false}render();return true}
function toast(t){$('toast').textContent=t;$('toast').classList.remove('hidden');clearTimeout(timer);timer=setTimeout(()=>$('toast').classList.add('hidden'),4500)}
function selectedMonth(){return $('month').value||dateStr().slice(0,7)}
function monthName(m=selectedMonth()){return new Date(m+'-02T12:00:00').toLocaleDateString('en-IN',{month:'long',year:'numeric'})}
function current(){return state.expenses.filter(e=>e.date.startsWith(selectedMonth()))}
function budgets(){return state.budgets[selectedMonth()]||{}}
function totals(){const a=current();return {spent:a.reduce((s,e)=>s+e.amount,0),budget:Object.values(budgets()).reduce((s,n)=>s+n,0)}}
function categorySpend(name){return current().filter(e=>e.category===name).reduce((s,e)=>s+e.amount,0)}
function showView(v){view=v;for(const b of document.querySelectorAll('[data-view]'))b.classList.toggle('active',b.dataset.view===v);const titles={overview:['A clearer picture of your money','Less guessing, more living. Let’s see where your money goes.'],expenses:['Every expense. One clear view','Keep track of the little things, so you can plan for the big ones.'],budgets:['Good plans make room for more','Build a budget that fits your student life.'],insights:['Understand your spending habits','A few useful numbers to help you make thoughtful choices.']};$('pageTitle').innerHTML=titles[v][0]+'<span>.</span>';$('pageDesc').textContent=titles[v][1];$('crumb').textContent=v==='expenses'?'All expenses':v[0].toUpperCase()+v.slice(1);$('overview-section').classList.toggle('hidden',v==='expenses'||v==='budgets');$('budgets-section').classList.toggle('hidden',v!=='budgets');$('insights-section').classList.toggle('hidden',v!=='insights');$('expense-section').classList.toggle('hidden',v==='budgets'||v==='insights');$('view-all').classList.toggle('hidden',v!=='overview');render()}
function render(){const a=current(),{spent,budget}=totals();$('spent').textContent=money(spent);$('budget-total').textContent=money(budget);$('remaining').textContent=budget?money(budget-spent):'—';$('count').textContent=a.length+' expense'+(a.length===1?'':'s')+' this month';$('edit-budget').innerHTML=(budget?'Adjust budgets':'Set your budget')+' <span>↗</span>';$('budget-status').textContent=!budget?'Set a budget to get started':spent>budget?'Over budget by '+money(spent-budget):Math.round(spent/budget*100)+'% of your monthly budget used';$('remaining').classList.toggle('negative',budget>0&&spent>budget);$('chart-total').textContent=money(spent);$('donut-total').textContent=money(spent);
const days=new Date(Number(selectedMonth().slice(0,4)),Number(selectedMonth().slice(5,7)),0).getDate();const daily=Array.from({length:days},(_,n)=>a.filter(e=>Number(e.date.slice(8))===n+1).reduce((s,e)=>s+e.amount,0));const max=Math.max(...daily,100);$('bars').innerHTML=daily.map((n,i)=>`<div class="bar-track"><div class="bar ${n?'':'zero'}" style="height:${n?Math.max(3,n/max*100):1}%" title="${i+1} ${safe(monthName())}: ${money(n)}" role="img" aria-label="Day ${i+1}: ${money(n)}"></div></div>`).join('');$('chart-labels').innerHTML=[1,Math.round(days/4),Math.round(days/2),Math.round(days*.75),days].map(n=>`<span>${String(n).padStart(2,'0')} ${new Date(selectedMonth()+'-02T12:00:00').toLocaleString('en-IN',{month:'short'})}</span>`).join('');
let cursor=0;const breakdown=cats.map(c=>({...c,total:categorySpend(c.name)})).filter(c=>c.total>0);const stops=breakdown.map(c=>{const start=cursor;cursor+=c.total/(spent||1)*100;return `${c.color} ${start}% ${cursor}%`});$('donut').style.background=spent?`conic-gradient(${stops.join(',')})`:'#edf0e8';$('category-legend').innerHTML=breakdown.length?breakdown.map(c=>`<div><span><i style="background:${c.color}"></i>${safe(c.name)}</span><b>${money(c.total)}</b><small>${Math.round(c.total/spent*100)}%</small></div>`).join(''):'<p class="muted center">Add expenses to see your breakdown.</p>';
const q=$('search').value.toLowerCase().trim(),cat=$('category-filter').value;let list=a.filter(e=>(!cat||e.category===cat)&&(e.title+' '+e.note+' '+e.payment).toLowerCase().includes(q));list.sort((x,y)=>$('sort').value==='high'?y.amount-x.amount:$('sort').value==='low'?x.amount-y.amount:y.date.localeCompare(x.date)||y.created-x.created);const filteredCount=list.length;if(view==='overview')list=list.slice(0,5);$('tableTitle').innerHTML=(view==='overview'?'Recent expenses':'All expenses')+` <span class="countbadge">${a.length}</span>`;
$('rows').innerHTML=list.map(e=>{const c=cats.find(c=>c.name===e.category);return `<tr><td><div class="expense-name"><span class="expense-icon" style="color:${c.color};background:${c.color}16">${c.icon}</span><div><strong>${safe(e.title)}</strong><small>${e.demo?'Sample data':safe(e.note||'Everyday expense')}</small></div></div></td><td><span class="category-pill" style="color:${c.color};background:${c.color}12">${safe(e.category)}</span></td><td>${new Date(e.date+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short'})}</td><td><span class="payment-dot"></span>${safe(e.payment)}</td><td class="amount">${money(e.amount)}</td><td class="row-actions"><button data-edit="${safe(e.id)}" title="Edit expense" aria-label="Edit ${safe(e.title)}">✎</button><button data-delete="${safe(e.id)}" title="Delete expense" aria-label="Delete ${safe(e.title)}">×</button></td></tr>`}).join('');$('empty').classList.toggle('hidden',list.length>0);if(!list.length){$('empty').querySelector('h3').textContent=a.length?'No matching expenses.':'A fresh start for your finances.';$('empty').querySelector('p').textContent=a.length?'Try a different search or category.':'Add your first expense, or try sample data to explore the dashboard.'}$('shown').textContent=`Showing ${list.length} of ${filteredCount} matching expenses`;
$('budget-cards').innerHTML=cats.map(c=>{const used=categorySpend(c.name),limit=budgets()[c.name]||0,over=limit&&used>limit;return `<article class="panel budget-card"><div class="budget-cat"><span style="color:${c.color}">${c.icon}</span><h3>${c.name}</h3></div><strong>${money(used)} <small>/ ${money(limit)}</small></strong><div class="progress"><span style="width:${limit?Math.min(100,used/limit*100):0}%;background:${over?'#bb7358':c.color}"></span></div><p>${!limit?'No budget set':over?money(used-limit)+' over budget':money(limit-used)+' remaining'}</p></article>`}).join('');
const top=[...breakdown].sort((x,y)=>y.total-x.total)[0];const avg=a.length?spent/days:0;$('insight-text').textContent=top?`${top.name} is your biggest spending category at ${money(top.total)}, accounting for ${Math.round(top.total/spent*100)}% of your monthly expenses.`:'Add your first expense to start discovering your spending habits.';const highest=[...a].sort((x,y)=>y.amount-x.amount)[0];$('insight-cards').innerHTML=[['Daily average',money(avg),'Across all '+days+' days of this month'],['Largest expense',highest?money(highest.amount):'—',highest?highest.title:'No expenses yet'],['Transactions',String(a.length),'Recorded in '+monthName()]].map(([title,note,sub])=>`<article class="panel budget-card"><p>${title}</p><strong>${note}</strong><p>${safe(sub)}</p></article>`).join('');const demo=a.some(e=>e.demo);$('demo').textContent=demo?'× Clear sample data':'✦ Try sample data';$('demo-label').textContent=demo?'SAMPLE DATA INCLUDED':'';
}
function openExpense(id){const e=state.expenses.find(e=>e.id===id);$('expense-form').reset();$('expense-id').value=e?.id||'';$('form-title').textContent=e?'Edit expense':'Add an expense';$('title').value=e?.title||'';$('amount').value=e?String(e.amount/100):'';$('date').value=e?.date||(selectedMonth()===dateStr().slice(0,7)?dateStr():selectedMonth()+'-01');$('date').max=dateStr();$('category').value=e?.category||cats[0].name;$('payment').value=e?.payment||'UPI';$('note').value=e?.note||'';$('expense-dialog').showModal();$('title').focus()}
function openBudget(){$('budget-month').textContent='Plan your category limits for '+monthName()+'. Use 0 for categories without a budget.';$('budget-inputs').innerHTML=cats.map((c,i)=>`<label class="budget-input"><span><i style="background:${c.color}"></i>${c.name}</span><div>₹ <input aria-label="${c.name} budget" data-budget="${c.name}" type="number" min="0" max="99999999" step="0.01" required value="${(budgets()[c.name]||0)/100}"></div></label>`).join('');$('budget-dialog').showModal()}
$('month').value=dateStr().slice(0,7);for(const id of ['category','category-filter'])$(id).insertAdjacentHTML('beforeend',cats.map(c=>`<option>${c.name}</option>`).join(''));
for(const b of document.querySelectorAll('[data-view]'))b.onclick=()=>showView(b.dataset.view);for(const id of ['add','empty-add','tip-add'])$(id).onclick=()=>openExpense();for(const id of ['edit-budget','budget-add'])$(id).onclick=openBudget;$('help').onclick=()=>$('help-dialog').showModal();$('view-all').onclick=()=>showView('expenses');
for(const b of document.querySelectorAll('[data-close]'))b.onclick=()=>$(b.dataset.close).close();for(const d of document.querySelectorAll('dialog'))d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});
for(const id of ['search','category-filter','sort'])$(id).addEventListener(id==='search'?'input':'change',render);$('month').onchange=()=>{if(!$('month').value)$('month').value=dateStr().slice(0,7);render()};for(const [id,step]of [['prev',-1],['next',1]])$(id).onclick=()=>{const d=new Date(selectedMonth()+'-02T12:00:00');d.setMonth(d.getMonth()+step);$('month').value=dateStr(d).slice(0,7);render()};
$('expense-form').onsubmit=e=>{e.preventDefault();const amount=Math.round(Number($('amount').value)*100),title=$('title').value.trim(),date=$('date').value;if(!title||!Number.isSafeInteger(amount)||amount<=0||amount>9999999900||date>dateStr()||!/^\d{4}-\d{2}-\d{2}$/.test(date)){toast('Enter a valid name, positive amount and a date up to today.');return}const id=$('expense-id').value,old=state.expenses.find(e=>e.id===id);const entry={id:id||uid(),title,amount,date,category:$('category').value,payment:$('payment').value,note:$('note').value.trim(),created:old?.created||Date.now(),demo:old?.demo||false};const next={...state,expenses:id?state.expenses.map(e=>e.id===id?entry:e):[...state.expenses,entry]};if(commit(next)){$('month').value=date.slice(0,7);render();$('expense-dialog').close();toast(id?'Expense updated.':'Expense added. One step towards smarter spending.')}};
$('budget-form').onsubmit=e=>{e.preventDefault();const b={};for(const input of document.querySelectorAll('[data-budget]')){const n=Math.round(Number(input.value)*100);if(!Number.isSafeInteger(n)||n<0||n>9999999900){toast('Enter a valid budget amount.');return}b[input.dataset.budget]=n}if(commit({...state,budgets:{...state.budgets,[selectedMonth()]:b}})){$('budget-dialog').close();toast('Your monthly budgets are saved.')}};
$('rows').onclick=e=>{const edit=e.target.closest('[data-edit]'),del=e.target.closest('[data-delete]');if(edit)openExpense(edit.dataset.edit);if(del){pendingDelete=del.dataset.delete;$('delete-dialog').showModal()}};$('confirm-delete').onclick=()=>{if(commit({...state,expenses:state.expenses.filter(e=>e.id!==pendingDelete)})){$('delete-dialog').close();toast('Expense deleted.')}};
$('demo').onclick=()=>{const m=selectedMonth();if(current().some(e=>e.demo)){if(commit({...state,expenses:state.expenses.filter(e=>!(e.demo&&e.date.startsWith(m)))}))toast('Sample expenses removed. Your own expenses and budgets are kept.');return}const last=m===dateStr().slice(0,7)?Number(dateStr().slice(8)):new Date(Number(m.slice(0,4)),Number(m.slice(5,7)),0).getDate();if(m>dateStr().slice(0,7)){toast('Choose the current month or an earlier month for sample data.');return}const sample=[['Cafeteria lunch',150,'Food & drinks','UPI',1],['Metro recharge',500,'Transport','UPI',2],['Notebook & stationery',320,'Education','Cash',3],['Coffee with friends',180,'Food & drinks','UPI',4],['Movie night',350,'Entertainment','Debit card',5],['Groceries',640,'Food & drinks','UPI',6],['Weekend essentials',850,'Shopping','Debit card',8],['Auto to campus',120,'Transport','Cash',10],['Printing project report',160,'Education','UPI',12],['Evening snacks',90,'Food & drinks','Cash',14]];const rows=sample.map(([title,n,category,payment,day],i)=>({id:uid(),title,amount:n*100,category,payment,date:m+'-'+String(Math.min(last,day)).padStart(2,'0'),note:'',created:Date.now()+i,demo:true}));if(commit({...state,expenses:[...state.expenses,...rows]}))toast('Sample expenses added. Set budgets to explore your spending plan.')};
$('export').onclick=()=>{const a=current();if(!a.length){toast('Add an expense before exporting this month.');return}const quote=v=>'"'+String(v).replace(/^[=+@\-\t\r]/,"'$&").replace(/"/g,'""')+'"';const csv='\uFEFF'+[['Expense','Amount (INR)','Category','Date','Payment','Note','Sample'],...a.map(e=>[e.title,(e.amount/100).toFixed(2),e.category,e.date,e.payment,e.note,e.demo?'Yes':'No'])].map(r=>r.map(quote).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const link=document.createElement('a');link.href=url;link.download='PocketWise-'+selectedMonth()+'.csv';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('CSV exported for '+monthName()+'.')};
window.addEventListener('storage',e=>{if(e.key==='pocketwise-v1')toast('Data changed in another tab. Refresh this page to load it.')});render();

document.querySelector('.brand').addEventListener('click',()=>showView('overview'));
